#include <iostream>
#include <vector>
using namespace std;

class LockManager {
    vector<bool> locks;
public:
    LockManager(int n = 10) : locks(n, false) {}

    bool acquire(int lockId) {
        if (locks[lockId]) {
            cout << "Lock " << lockId << ": ACQUIRE FAIL" << endl;
            return false;
        }
        locks[lockId] = true;
        cout << "Lock " << lockId << ": ACQUIRE OK" << endl;
        return true;
    }

    void release(int lockId) {
        locks[lockId] = false;
        cout << "Lock " << lockId << ": RELEASED" << endl;
    }
};

int main() {
    LockManager lm;
    cout << "Client 1: "; lm.acquire(0);
    cout << "Client 2: "; lm.acquire(0);
    cout << "Client 1: "; lm.release(0);
    cout << "Client 2: "; lm.acquire(0);
    return 0;
}
